commands.command:
$rp4PreviewRoot = 'private-input/74505a07063f05bbf8f0'
if (Test-Path -LiteralPath $rp4PreviewRoot) { throw 'PREVIEW_PATH_ALREADY_EXISTS' }
New-Item -Path $rp4PreviewRoot -ItemType Directory | Out-Null
$rp4PreviewCode = @'
const fs=require("node:fs");
const crypto=require("node:crypto");
const sharp=require("private-input/e21fa9007c3e05406e48");
(async()=>{
 const result=[];
 for(const name of ["B1_over_B0","B2_over_B1"]){
  const input="private-input/41501f2ad7133ee02e73"+name+".svg";
  const output="private-input/03950049873df9831cfc"+name+".png";
  if(fs.existsSync(output)) throw new Error("IMMUTABLE_PREVIEW_EXISTS");
  const info=await sharp(input).png().toFile(output);
  result.push({input,output,width:info.width,height:info.height,sha256:crypto.createHash("sha256").update(fs.readFileSync(output)).digest("hex")});
 }
 process.stdout.write(JSON.stringify({status:"PREVIEWS_RENDERED",files:result})+"\n");
})().catch(e=>{process.stderr.write(String(e));process.exitCode=1;});
'@
& 'private-input/ee2260aecd0f080d2217' -e $rp4PreviewCode
exit $LASTEXITCODE

